async (page) => {
    const { execSync } = require('child_process');

    try {
        // Make the script executable
        execSync('chmod +x /tmp/mcp-workspace/monitor_cpu.sh');

        // Execute the script
        const output = execSync('bash /tmp/mcp-workspace/monitor_cpu.sh', { 
            encoding: 'utf-8',
            timeout: 70000 // 70 seconds to allow for 60 seconds of monitoring
        });

        console.log('Script output:');
        console.log(output);

        return 'Script executed successfully';
    } catch (error) {
        console.error('Error:', error.message);
        return 'Error: ' + error.message;
    }
}

